(()=>{'use strict';
const $=id=>document.getElementById(id), $$=s=>[...document.querySelectorAll(s)],
 esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),
 safeUrl=x=>{try{const u=new URL(x);return u.protocol==='https:'?u.href:null}catch{return null}},
 money=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2,minimumFractionDigits:2}),
 num=n=>Number(n||0).toLocaleString(),
 fmtDate=d=>d?new Date(d).toLocaleString(S.lang==='uk'?'uk-UA':S.lang==='en'?'en-GB':'ru-RU'): '—',
 cfg=window.YANE_CONFIG||{},
 S={sb:null,user:null,profile:null,profiles:[],chats:[],oldest:null,hasMore:false,reply:null,lang:localStorage.getItem('ycl-language')||'ru',theme:localStorage.getItem('ycl-theme')||'light',page:'home',adminTab:'reports',authMode:'login',stats:[],clips:[],videos:[],lessons:[],releases:[],settings:null,selectedUser:null,month:new Date().toISOString().slice(0,7),busy:false,chatChannel:null,lastAction:Date.now(),fx:null,openedProfile:null,aiHistory:[],aiImage:null,aiImageName:'',aiVideoFile:null,latestReport:null,profileMetrics:{},aiBusy:false};
const dict={
ru:{tagline:'КРЕАТОР ПЛАТФОРМА',navHome:'Главная',navAI:'ЯнеИИ',navSchool:'Школа монтажа',navDiagnose:'Диагностика',navVideos:'Видео',navClippers:'Нарезчики',navChat:'Общий чат',navStats:'Календарь и статистика',navRules:'Правила',navAdmin:'Управление',createContent:'Предложить видео',heroTitle:'Спроси',heroText:'Твой помощник по TikTok, Shorts, монтажу, дизайну, аналитике и созданию нарезок. Конкретные советы и пошаговые инструкции.',askAI:'Спросить ЯнеИИ →',fastActions:'Быстрые действия',quickAI:'Разбор и советы по монтажу',quickSchool:'Уроки и эффекты',quickStats:'Твой прогресс',quickChat:'Помощь нарезчиков',showAll:'Смотреть все →',yourProgress:'Твой прогресс',openCalendar:'Открыть календарь',aiTitle:'ЯнеИИ — твой помощник',aiSubtitle:'Спроси об эффектах, монтаже, музыке, просмотрах и загрузи фото для разбора.',schoolSub:'Подробные уроки для начинающих и опытных нарезчиков.',diagnoseSub:'Найди проблему и получи конкретные шаги её решения.',videosSub:'Подборка реальных нарезок, одобренных администрацией.',proposeVideo:'＋ Предложить видео',clippersSub:'Основной состав, связанный с настоящими аккаунтами.',occupiedSeats:'Места в основе',chatSub:'Сообщения синхронизируются через Supabase. Возле каждого сообщения есть кнопка жалобы.',send:'Отправить',calendar:'Календарь',rulesSub:'Подтверждённые правила и дополнительные положения сообщества.',profile:'Профиль'},
uk:{tagline:'ПЛАТФОРМА КРЕАТОРІВ',navHome:'Головна',navAI:'ЯнеШІ',navSchool:'Школа монтажу',navDiagnose:'Діагностика',navVideos:'Відео',navClippers:'Нарізувачі',navChat:'Спільний чат',navStats:'Календар і статистика',navRules:'Правила',navAdmin:'Керування',createContent:'Запропонувати відео',heroTitle:'Запитай',heroText:'Твій помічник із TikTok, Shorts, монтажу, дизайну, аналітики та створення нарізок. Покрокові інструкції.',askAI:'Запитати ЯнеШІ →',fastActions:'Швидкі дії',quickAI:'Аналіз і поради щодо монтажу',quickSchool:'Уроки та ефекти',quickStats:'Твій прогрес',quickChat:'Допомога спільноти',showAll:'Переглянути все →',yourProgress:'Твій прогрес',openCalendar:'Відкрити календар',aiTitle:'ЯнеШІ — твій помічник',aiSubtitle:'Запитай про ефекти, монтаж, музику, перегляди та додай фото.',schoolSub:'Детальні уроки для початківців і досвідчених авторів.',diagnoseSub:'Знайди проблему та отримай покрокове рішення.',videosSub:'Добірка реальних нарізок, схвалених адміністрацією.',proposeVideo:'＋ Запропонувати відео',clippersSub:'Основна команда зі справжніми обліковими записами.',occupiedSeats:'Місця в команді',chatSub:'Повідомлення синхронізуються через Supabase. Біля кожного є кнопка скарги.',send:'Надіслати',calendar:'Календар',rulesSub:'Підтверджені правила та додаткові положення спільноти.',profile:'Профіль'},
en:{tagline:'CREATOR PLATFORM',navHome:'Home',navAI:'YaneAI',navSchool:'Editing school',navDiagnose:'Troubleshooting',navVideos:'Videos',navClippers:'Clippers',navChat:'Community chat',navStats:'Calendar & statistics',navRules:'Rules',navAdmin:'Administration',createContent:'Suggest video',heroTitle:'Ask',heroText:'Your assistant for TikTok, Shorts, editing, design, analytics, and stream clips. Practical step-by-step guidance.',askAI:'Ask YaneAI →',fastActions:'Quick actions',quickAI:'Video reviews and editing tips',quickSchool:'Lessons and effects',quickStats:'Your progress',quickChat:'Creator community help',showAll:'View all →',yourProgress:'Your progress',openCalendar:'Open calendar',aiTitle:'YaneAI — your assistant',aiSubtitle:'Ask about effects, editing, sound, views, or attach a photo.',schoolSub:'Detailed tutorials for beginner and experienced editors.',diagnoseSub:'Find a problem and get actionable steps.',videosSub:'Real clips approved by community administrators.',proposeVideo:'＋ Suggest video',clippersSub:'Core editors linked to real user accounts.',occupiedSeats:'Core team seats',chatSub:'Messages sync through Supabase. You can report any message.',send:'Send',calendar:'Calendar',rulesSub:'Confirmed rules and additional community policies.',profile:'Profile'}};
function t(key){return (dict[S.lang]||dict.ru)[key]||dict.ru[key]||key}
function toast(msg){const el=$('toast');el.textContent=String(msg);el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),4300)}
function html(id,content){const el=$(id);if(el)el.innerHTML=content}
function isAdmin(){return !!S.profile&&S.profile.role==='admin'&&!S.profile.is_banned}
function signed(){return !!S.user&&!!S.profile&&!S.profile.is_banned}
function checkAuth(){if(!S.sb){toast('Сначала подключи Supabase — см. README_УСТАНОВКА.md');return false}if(!S.user){$('auth-dialog').showModal();toast('Нужен аккаунт');return false}if(S.profile?.is_banned){toast('Этот аккаунт заблокирован администрацией');return false}return true}
function requireAdmin(){if(!isAdmin()){toast('Доступ только для администрации');return false}return true}
function avatar(p,extra=''){const name=String(p?.username||p?.display_name||'Y');const url=safeUrl(p?.avatar_url);return `<span class="small-avatar ${extra}">${url?`<img src="${esc(url)}" alt="">`:esc(name.slice(0,1).toUpperCase())}</span>`}
function roleLabel(p){return p?.role==='admin'?'🛡 Администратор':p?.role==='clipper'?'🎬 Основной нарезчик':'👤 Пользователь'}
function go(page){if(page==='admin'&&!requireAdmin())return;S.page=page;$$('.screen').forEach(el=>el.classList.toggle('active',el.id==='screen-'+page));$$('[data-nav]').forEach(el=>el.classList.toggle('nav-active',el.dataset.nav===page));$('app').classList.remove('menu-open');$('scrim').hidden=true;window.scrollTo({top:0,behavior:'instant'});history.replaceState(null,'','#'+page);if(page==='chat')loadChat();if(page==='stats')loadStats();if(page==='videos')loadVideos();if(page==='clippers')loadClippers();if(page==='admin')renderAdmin();if(page==='school')loadLessons();if(page==='rules')renderRules()}
function setTheme(theme){S.theme=theme==='dark'?'dark':'light';$('app').dataset.theme=S.theme;$('theme-toggle').textContent=S.theme==='dark'?'☀':'☾';localStorage.setItem('ycl-theme',S.theme);if(signed())savePreferences()}
function setLanguage(lang){S.lang=['ru','uk','en'].includes(lang)?lang:'ru';document.documentElement.lang=S.lang;$('language-select').value=S.lang;localStorage.setItem('ycl-language',S.lang);$$('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n)});if(signed())savePreferences();renderStats();renderLessons();renderDiagnostics();renderRules();renderClippers();renderVideos();renderProfile()}
async function savePreferences(){if(!S.sb||!S.profile)return;const p=S.profile;const {error}=await S.sb.rpc('v11_update_profile',{new_name:p.username,new_avatar:p.avatar_url||'',new_socials:p.social_links||{},new_language:S.lang,new_theme:S.theme});if(error)console.warn('Preferences:',error.message)}
function connection(ok){$('connection-status').textContent=ok?'Supabase подключён':'Нужна настройка Supabase';$('sidebar').querySelector('.live-dot').classList.toggle('on',ok);$('chat-status').textContent=ok?'ONLINE':'OFFLINE'}
// This function never invents connection, users or content if Supabase is not configured.
async function initBackend(){if(!cfg.supabaseUrl||!cfg.supabaseAnonKey){connection(false);showDisconnected();return}if(!window.supabase?.createClient){connection(false);toast('Библиотека Supabase не загрузилась. Проверь интернет.');return}try{S.sb=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});S.sb.auth.onAuthStateChange((event,session)=>{setTimeout(async()=>{if(event==='PASSWORD_RECOVERY'){S.user=session?.user||null;const pw=prompt('Ссылка подтверждена. Введи новый пароль (от 8 символов):');if(pw?.length>=8){const {error}=await S.sb.auth.updateUser({password:pw});toast(error?error.message:'Пароль обновлён')} } await setSession(session?.user||null)},0)});const {data:{user},error}=await S.sb.auth.getUser();if(error&&error.message&&!/missing auth session/i.test(error.message))console.warn(error.message);await setSession(user||null);connection(true);await Promise.allSettled([loadPublic(),loadReleases()]);S.chatChannel=S.sb.channel('ycl-v11-chat').on('postgres_changes',{event:'*',schema:'public',table:'chat_messages'},()=>{if(S.page==='chat')loadChat()}).subscribe();}catch(e){connection(false);toast('Supabase: '+e.message)}}
function showDisconnected(){html('featured-videos','<div class="empty">Подключи Supabase, чтобы публиковать настоящие видео.</div>');html('clippers-list','<div class="empty">Нужна база пользователей Supabase.</div>');html('lessons-list','<div class="empty">Подключи Supabase, затем администратор сможет добавлять уроки.</div>');html('chat-stream','<div class="empty">Чат требует Supabase. См. инструкцию по установке.</div>');renderStats()}
async function setSession(user){const oldId=S.user?.id;S.user=user;S.profile=null;if(user&&S.sb){const {data,error}=await S.sb.from('profiles').select('*').eq('id',user.id).maybeSingle();if(error)console.warn('Profile:',error.message);S.profile=data||null}const p=S.profile;html('top-avatar',p?avatar(p).replace(/^<span[^>]*>|<\/span>$/g,''): 'Y');$('top-account-label').textContent=p?p.username:'Войти';$('side-username').textContent=p?p.username:'Гость';$('side-role').textContent=p?roleLabel(p):'Войти или зарегистрироваться';html('side-avatar',p?avatar(p).replace(/^<span[^>]*>|<\/span>$/g,''):'Y');$$('.admin-only').forEach(el=>el.hidden=!isAdmin());if(!isAdmin()&&S.page==='admin')go('home');if(p){if(['ru','uk','en'].includes(p.language))S.lang=p.language;if(['light','dark'].includes(p.theme))S.theme=p.theme}setTheme(S.theme);setLanguage(S.lang);renderProfile();if(p)loadProfileMetrics(p.id);if(oldId!==user?.id){S.aiHistory=[];S.aiImage=null;S.aiVideoFile=null;S.latestReport=null;html('ai-messages','<div class="ai-answer"><b>ЯнеИИ ✦</b><p>Привет! Какой монтаж или эффект разберём?</p></div>')}if(user&&S.sb){await Promise.allSettled([loadStats(),loadChat(),loadMySubmissions()]);loadAIHistory();loadLatestReport();if(!S.activityTimer){S.activityTimer=setInterval(activityPulse,60000)}activityPulse()}else{S.stats=[];S.chats=[];renderStats();renderChat();}renderVideos()}
async function loadProfiles(){if(!S.sb||!signed())return;const {data,error}=await S.sb.from('profiles').select('id,username,display_name,avatar_url,role,created_at,activity_seconds,last_seen_at,is_banned,chat_muted_until,social_links').limit(1000);if(!error)S.profiles=data||[]}
async function loadPublic(){if(!S.sb)return;const jobs=[S.sb.from('site_settings').select('*').eq('id','main').maybeSingle(),S.sb.from('featured_videos').select('*').order('created_at',{ascending:false}).limit(30)];const [settings,vids]=await Promise.all(jobs);if(!settings.error)S.settings=settings.data;if(!vids.error)S.videos=vids.data||[];renderRules();renderVideos();renderClippers();if(S.settings?.insert_download_url&&safeUrl(S.settings.insert_download_url)){$('insert-download').href=safeUrl(S.settings.insert_download_url);$('insert-download').hidden=false}}
function formatError(e){return String(e?.message||e||'Неизвестная ошибка').slice(0,250)}
// Authentication, password reset and public profile.
function authMode(mode){S.authMode=mode;$$('[data-authmode]').forEach(b=>b.classList.toggle('active',b.dataset.authmode===mode));$('auth-nickname-label').hidden=mode!=='signup';$('auth-confirm-label').hidden=mode!=='signup';$('auth-password-label').hidden=mode==='reset';$('auth-password').required=mode!=='reset';$('auth-nickname').required=mode==='signup';$('auth-confirm').required=mode==='signup';$('auth-submit').textContent=mode==='signup'?'Создать аккаунт':mode==='reset'?'Отправить письмо':'Войти';$('auth-help').textContent=mode==='signup'?'Для восстановления доступа нужен действительный email. Пароль хранится в Supabase Auth, не на сайте.':mode==='reset'?'Получишь ссылку на email для сброса пароля.':'Email нужен для безопасного восстановления пароля.'}
async function authSubmit(e){e.preventDefault();if(!S.sb)return toast('Сначала настрой Supabase');const email=$('auth-email').value.trim(),password=$('auth-password').value,nick=$('auth-nickname').value.trim();let res;if(S.authMode==='signup'){if(password!==$('auth-confirm').value)return toast('Пароли не совпадают');if(!/^[a-zA-Z0-9_]{3,24}$/.test(nick))return toast('Ник: 3–24 символа, латиница, цифры или _');res=await S.sb.auth.signUp({email,password,options:{data:{username:nick},emailRedirectTo:location.origin+location.pathname}})}else if(S.authMode==='reset'){res=await S.sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname})}else res=await S.sb.auth.signInWithPassword({email,password});if(res.error)return toast('Ошибка авторизации: '+formatError(res.error));$('auth-dialog').close();toast(S.authMode==='reset'?'Проверь почту':S.authMode==='signup'&&!res.data.session?'Проверь почту для подтверждения аккаунта':'Успешный вход');if(res.data?.user&&res.data?.session)await setSession(res.data.user)}
async function openProfile(id){if(!S.sb||!checkAuth())return;if(id){const {data,error}=await S.sb.from('profiles').select('id,username,display_name,avatar_url,role,created_at,activity_seconds,last_seen_at,social_links').eq('id',id).maybeSingle();if(error)return toast(formatError(error));S.openedProfile=data}else S.openedProfile=S.profile;go('profile');renderProfile();loadProfileMetrics(S.openedProfile?.id)}
function renderProfile(){if(!S.page||!$('profile-detail'))return;const p=S.openedProfile||S.profile;if(!p){html('profile-detail','<div class="empty">Войди, чтобы открыть свой профиль.</div>');$('profile-editor').hidden=true;return}html('profile-detail',`<div class="card"><div class="clipper-card">${avatar(p)}<div><h2>${esc(p.username)}</h2><span class="role-label">${roleLabel(p)}</span></div></div><div class="stat-cards" style="margin-top:18px"><div class="card"><span>Дата регистрации</span><strong style="font-size:14px">${esc(fmtDate(p.created_at).split(',')[0])}</strong></div><div class="card"><span>Реальная активность</span><strong>${Math.round((p.activity_seconds||0)/60)} мин</strong></div><div class="card"><span>Последняя активность</span><strong style="font-size:14px">${esc(fmtDate(p.last_seen_at))}</strong></div><div class="card"><span>Сообщений</span><strong>${S.profileMetrics[p.id]?num(S.profileMetrics[p.id].message_count):'—'}</strong></div><div class="card"><span>Опубликованных видео</span><strong>${S.profileMetrics[p.id]?num(S.profileMetrics[p.id].video_count):'—'}</strong></div><div class="card"><span>Просмотров в статистике</span><strong>${S.profileMetrics[p.id]?num(S.profileMetrics[p.id].view_count):'—'}</strong></div></div><div class="muted">${Object.entries(p.social_links||{}).map(([k,v])=>safeUrl(v)?`<a href="${esc(safeUrl(v))}" target="_blank" rel="noopener noreferrer">${esc(k)} ↗</a>`:'').join('　')}</div></div>`);const own=S.user?.id===p.id;$('profile-editor').hidden=!own;if(own){$('profile-name').value=p.username||'';$('profile-avatar').value=p.avatar_url||'';$('profile-tiktok').value=p.social_links?.tiktok||'';$('profile-telegram').value=p.social_links?.telegram||''}}
async function loadProfileMetrics(id){if(!signed()||!id)return;const {data,error}=await S.sb.rpc('v11_public_profile_stats',{target_user:id});if(!error&&data?.[0]){S.profileMetrics[id]=data[0];if(S.page==='profile'&&(S.openedProfile?.id||S.profile?.id)===id)renderProfile()}}
async function saveProfile(e){e.preventDefault();if(!checkAuth())return;const name=$('profile-name').value.trim(),avatarUrl=$('profile-avatar').value.trim(),socials={};for(const k of ['tiktok','telegram']){const val=$('profile-'+k).value.trim();if(val){if(!safeUrl(val))return toast('Только HTTPS-ссылки');socials[k]=val}}const {error}=await S.sb.rpc('v11_update_profile',{new_name:name,new_avatar:avatarUrl,new_socials:socials,new_language:S.lang,new_theme:S.theme});if(error)return toast(formatError(error));toast('Профиль сохранён');await setSession(S.user);S.openedProfile=S.profile;renderProfile()}
async function activityPulse(){if(!signed()||document.hidden||Date.now()-S.lastAction>150000)return;try{await S.sb.rpc('v11_activity_ping')}catch{}}
// Chat with pagination, live updates, safe escaping, replies and reporting.
async function loadChat(older=false){if(!S.sb||!signed())return;if(older&&!S.oldest)return;let q=S.sb.from('chat_messages').select('id,author_id,body,created_at,reply_to,removed').eq('removed',false).order('created_at',{ascending:false}).limit(35);if(older)q=q.lt('created_at',S.oldest);const {data,error}=await q;if(error){html('chat-stream','<div class="empty">Ошибка чата: '+esc(error.message)+'</div>');return}const rows=(data||[]).reverse();if(older){const prior=new Set(S.chats.map(x=>x.id));S.chats=[...rows.filter(x=>!prior.has(x.id)),...S.chats]}else S.chats=rows;S.oldest=S.chats[0]?.created_at||null;S.hasMore=(data||[]).length===35;$('older-chat').hidden=!S.hasMore;await loadProfiles();renderChat(older)}
function renderChat(older=false){const box=$('chat-stream');if(!signed()){box.innerHTML='<div class="empty">Войди, чтобы читать чат и отправлять сообщения.</div>';return}const byId=new Map(S.profiles.map(x=>[x.id,x])),msgs=new Map(S.chats.map(x=>[x.id,x]));box.innerHTML=S.chats.length?S.chats.map(m=>{const u=byId.get(m.author_id),reply=m.reply_to?msgs.get(m.reply_to):null;return `<article class="chat-bubble ${m.author_id===S.user.id?'mine':''}"><div class="bubble-header">${avatar(u)}<button data-user="${esc(m.author_id)}">${esc(u?.username||'Участник')}</button><span class="role-label">${esc(roleLabel(u))}</span><span class="muted">${esc(fmtDate(m.created_at))}</span></div>${reply?`<small class="muted">↩ ${esc(reply.body.slice(0,100))}</small>`:''}<div class="bubble-text">${esc(m.body)}</div><div class="bubble-actions"><button data-reply="${esc(m.id)}">↩ Ответить</button>${m.author_id!==S.user.id?`<button data-report-message="${esc(m.id)}">⚑ Жалоба</button>`:''}${isAdmin()?`<button data-delete-message="${esc(m.id)}">✕ Удалить</button>`:''}</div></article>`}).join(''):'<div class="empty">Пока сообщений нет. Начни общение!</div>';if(!older)box.scrollTop=box.scrollHeight}
async function sendChat(){if(!checkAuth())return;const body=$('chat-input').value.trim();if(!body||body.length>1000)return toast('Сообщение: от 1 до 1000 символов');$('chat-send').disabled=true;try{const {error}=await S.sb.from('chat_messages').insert({author_id:S.user.id,body,reply_to:S.reply});if(error)throw error;$('chat-input').value='';S.reply=null;$('chat-reply').hidden=true;await loadChat()}catch(e){toast(formatError(e))}finally{$('chat-send').disabled=false}}
function openReport(id){if(!checkAuth())return;$('report-message-id').value=id;$('report-comment').value='';$('report-dialog').showModal()}
async function submitReport(e){e.preventDefault();if(!checkAuth())return;const reason=$('report-reason').value,comment=$('report-comment').value.trim(),text=(reason+(comment?' — '+comment:'')).slice(0,250);const {error}=await S.sb.from('chat_reports').insert({reporter_id:S.user.id,message_id:$('report-message-id').value,reason:text});if(error)return toast(error.code==='23505'?'Ты уже пожаловался на это сообщение':formatError(error));$('report-dialog').close();toast('Жалоба отправлена в администрацию')}
async function deleteChat(id){if(!requireAdmin()||!confirm('Скрыть сообщение для всех?'))return;const {error}=await S.sb.rpc('v11_delete_message',{message_id:id});if(error)return toast(formatError(error));await loadChat();toast('Сообщение скрыто')}
// Videos and submissions use only real admin-approved URLs.
async function loadVideos(){if(!S.sb){renderVideos();return}const {data,error}=await S.sb.from('featured_videos').select('*').order('created_at',{ascending:false}).limit(25);if(!error)S.videos=data||[];renderVideos();if(signed())loadMySubmissions()}
function player(url){const href=safeUrl(url);if(!href)return'<div class="video-preview">▣</div>';try{const u=new URL(href),host=u.hostname.replace(/^www\./,'');let id='';if(host==='youtu.be')id=u.pathname.split('/')[1];else if(['youtube.com','m.youtube.com'].includes(host))id=u.searchParams.get('v')||u.pathname.match(/^\/shorts\/([^/]+)/)?.[1];if(id&&/^[\w-]{11}$/.test(id))return `<div class="video-preview"><iframe loading="lazy" title="YouTube video" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>`;if(u.pathname.toLowerCase().endsWith('.mp4'))return `<div class="video-preview"><video controls preload="metadata" playsinline src="${esc(href)}"></video></div>`}catch{}return'<div class="video-preview">▶</div>'}
function videoCard(v){return `<article class="card video-card">${player(v.source_url)}<h3>${esc(v.title)}</h3><p>Автор: ${esc(v.author)}</p><p>${esc(v.description||'')}</p><div class="meta">${esc(fmtDate(v.created_at))}</div><div class="video-actions"><a class="btn btn-secondary" href="${esc(safeUrl(v.source_url)||'#')}" target="_blank" rel="noopener noreferrer">Смотреть оригинал ↗</a><button class="btn btn-secondary" data-ai-video="${esc(v.id)}">✦ Обсудить с ЯнеИИ</button></div></article>`}
function renderVideos(){const list=S.videos.length?S.videos.map(videoCard).join(''):'<div class="empty">Пока нет одобренных роликов. Участники могут предложить свои работы.</div>';html('featured-videos',list);html('home-videos',S.videos.length?S.videos.slice(0,3).map(videoCard).join(''):'<div class="empty">Здесь появятся проверенные видео участников.</div>')}
async function sendSubmission(e){e.preventDefault();if(!checkAuth())return;const f=new FormData(e.target),url=safeUrl(f.get('source_url'));if(!url)return toast('Укажи правильную HTTPS-ссылку');const {error}=await S.sb.from('video_submissions').insert({author_id:S.user.id,title:String(f.get('title')).trim(),description:String(f.get('description')||'').trim(),author_credit:String(f.get('author_credit')).trim(),source_url:url});if(error)return toast(formatError(error));$('submission-dialog').close();e.target.reset();toast('Заявка отправлена администраторам');loadMySubmissions()}
async function loadMySubmissions(){if(!signed()){$('my-submissions-card').hidden=true;return}const {data,error}=await S.sb.from('video_submissions').select('title,status,review_reason,created_at').eq('author_id',S.user.id).order('created_at',{ascending:false}).limit(25);if(error)return;$('my-submissions-card').hidden=false;html('my-submissions',data?.length?`<div class="table-scroll"><table><thead><tr><th>Название</th><th>Дата</th><th>Решение</th><th>Комментарий</th></tr></thead><tbody>${data.map(v=>`<tr><td>${esc(v.title)}</td><td>${esc(fmtDate(v.created_at))}</td><td>${esc(v.status)}</td><td>${esc(v.review_reason||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<p>Заявок пока нет.</p>')}
async function loadClippers(){if(S.sb&&signed())await loadProfiles();renderClippers()}
function renderClippers(){const list=S.profiles.filter(x=>x.role==='clipper'),cap=Number(S.settings?.capacity||10);$('clippers-capacity').textContent=list.length+' / '+cap;html('clippers-list',list.length?list.map(p=>`<div class="card clipper-card">${avatar(p)}<div><b>${esc(p.username)}</b><small class="muted">🎬 Основной нарезчик</small><button class="link-btn" data-user="${esc(p.id)}">Открыть профиль →</button></div></div>`).join(''):'<div class="empty">Основной состав ещё не назначен администратором.</div>')}
function renderRules(){const s=S.settings;html('rules-boxes',`<div class="card"><h3>Правила Янехера</h3><p>${esc(s?.official_rules||'Официальные правила не опубликованы. Администрация добавит только подтверждённые материалы.')}</p></div><div class="card"><h3>Правила сообщества</h3><p>${esc(s?.extra_rules||'Дополнительные правила пока не опубликованы администрацией.')}</p></div><div class="card"><h3>Правила чата</h3><p>Уважайте участников. Не отправляйте спам и угрозы. Используйте кнопку «Жалоба» возле сообщения, если заметили нарушение.</p></div><div class="card"><h3>Публикация видео</h3><p>Предлагайте только работы, на которые у вас есть права или разрешение автора. Подборка модерируется.</p></div>`);$('rules-banner').hidden=!s?.banner_path;if(s?.banner_path&&S.sb){const pub=S.sb.storage.from('banners').getPublicUrl(s.banner_path);if(pub.data?.publicUrl){$('rules-image').src=pub.data.publicUrl;$('rules-download').href=pub.data.publicUrl;$('rules-download').download=s.banner_path.split('/').pop()||'banner.png'}}}
// Cloud-based per-user video tracker; 5,000-view threshold and real role-based earnings.
async function loadStats(){if(!signed()){S.stats=[];renderStats();return}const {data,error}=await S.sb.from('video_stats').select('*').eq('owner_id',S.user.id).order('posted_on',{ascending:false}).limit(1000);if(error){toast('Календарь: '+formatError(error));return}S.stats=data||[];renderStats();legacyNotice();if(S.profile?.role==='clipper'&&!S.fx)fetchRates()}
function activeStats(){return S.stats.filter(x=>x.posted_on?.startsWith(S.month))}
function calculated(){const valid=S.stats.filter(x=>Number(x.views)>=5000),sum=valid.reduce((a,x)=>a+Number(x.views),0),earn=sum*150/1e6;return{valid,sum,earn}}
function monthLabel(month){return new Date(month+'-01T12:00:00').toLocaleDateString(S.lang==='en'?'en-GB':S.lang==='uk'?'uk-UA':'ru-RU',{month:'long',year:'numeric'})}
function amount(usd){const cur=S.lang==='ru'?'RUB':S.lang==='uk'?'UAH':'USD';if(cur==='USD')return '$'+money(usd);const rate=S.fx?.rates?.[cur];return Number.isFinite(rate)?(usd*rate).toLocaleString(S.lang==='ru'?'ru-RU':'uk-UA',{style:'currency',currency:cur,maximumFractionDigits:2}):'$'+money(usd)+' (нет курса '+cur+')'}
async function fetchRates(){try{const resp=await fetch('https://open.er-api.com/v6/latest/USD',{cache:'no-store',signal:AbortSignal.timeout(7000)});const data=await resp.json();if(data.result!=='success'||!Number.isFinite(data.rates?.UAH)||!Number.isFinite(data.rates?.RUB))return;S.fx=data;renderStats()}catch(e){console.warn('FX unavailable, USD fallback')}}
function renderStats(){if(!$('stats-title'))return;const clipper=S.profile?.role==='clipper',list=activeStats(),eligible=list.filter(x=>Number(x.views)>=5000),views=eligible.reduce((s,x)=>s+Number(x.views),0),global=calculated(),earned=views*150/1e6;$('stats-title').textContent=clipper?'💰 Мой заработок':'Путь к 500 000 просмотров';$('stats-hint').textContent=clipper?'⚠️ Доход расчётный: $150 за 1 000 000 просмотров. Учитываются видео от 5 000 просмотров. Фактическая выплата может отличаться.':'⚠️ В статистику засчитываются только видео от 5 000 просмотров.';
 const today=new Date(),weekago=new Date(Date.now()-7*86400000).toISOString().slice(0,10),todayISO=new Date().toISOString().slice(0,10);
 const summ=clipper?[
 ['За сегодня',amount(global.valid.filter(x=>x.posted_on===todayISO).reduce((s,x)=>s+Number(x.views),0)*.00015)],['За 7 дней',amount(global.valid.filter(x=>x.posted_on>=weekago).reduce((s,x)=>s+Number(x.views),0)*.00015)],['За месяц',amount(earned)],['За всё время',amount(global.earn)],['Всего просмотров',num(global.sum)],['Засчитанных роликов',num(global.valid.length)]]:[['Просмотры месяца',num(views)],['Прогресс',Math.min(100,Math.round(views/500000*100))+'%'],['До цели',num(Math.max(0,500000-views))],['Засчитано видео',num(eligible.length)],['Всего роликов',num(list.length)]];
 html('stat-summary',summ.map(([k,v])=>`<div class="card"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join(''));$('home-progress-title').textContent=!signed()?'Войди, чтобы увидеть личную статистику.':clipper?'Ориентировочный доход за всё время':'Путь к 500 000 просмотров';$('home-progress-value').textContent=!signed()?'—':clipper?amount(global.earn):num(global.sum)+' / 500 000';$('home-progress-bar').style.width=clipper?'0%':Math.min(100,global.sum/500000*100)+'%';$('month-title').textContent=monthLabel(S.month);
 const year=Number(S.month.slice(0,4)),month=Number(S.month.slice(5,7))-1,nDays=new Date(year,month+1,0).getDate(),before=(new Date(year,month,1).getDay()+6)%7,perDay=new Map();for(const x of list){const day=Number(x.posted_on.slice(-2));perDay.set(day,(perDay.get(day)||0)+(Number(x.views)>=5000?Number(x.views):0))}
 html('calendar-days','<span></span>'.repeat(before)+Array.from({length:nDays},(_,i)=>{const day=i+1,vc=perDay.get(day)||0;return `<button data-stat-day="${day}" title="${day}: ${num(vc)}"><b>${day}</b><small>${vc?clipper?amount(vc*.00015):num(vc):'—'}</small></button>`}).join(''));
 html('stats-journal',list.length?`<div class="table-scroll"><table><thead><tr><th>Дата</th><th>Видео</th><th>Просмотры</th><th>${clipper?'Доход':'Статус'}</th><th>Действия</th></tr></thead><tbody>${list.map(x=>`<tr><td>${esc(x.posted_on)}</td><td>${esc(x.title)}</td><td>${num(x.views)}</td><td>${Number(x.views)>=5000?clipper?esc(amount(Number(x.views)*.00015)):'✓ Засчитано':'Не достигнут порог 5000'}</td><td><div class="table-actions"><button data-edit-stat="${esc(x.id)}">Изменить</button><button data-delete-stat="${esc(x.id)}">Удалить</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">За выбранный месяц видео пока не добавлены.</div>');if(clipper){const el=$('stats-hint');el.textContent+=' '+(S.fx?.time_last_update_utc?'Курс USD от '+S.fx.time_last_update_utc+'.':S.lang!=='en'?'Конвертация недоступна — показываем USD.':'');}}
async function saveStat(e){e.preventDefault();if(!checkAuth())return;const id=$('stat-id').value,title=$('stat-name').value.trim(),date=$('stat-date').value,views=Number($('stat-views').value),link=$('stat-url').value.trim();if(!title||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isSafeInteger(views)||views<0||views>1e10)return toast('Неверные данные записи');if(link&&!safeUrl(link))return toast('Ссылка должна начинаться с HTTPS');const data={title,posted_on:date,views,source_url:link||null};const req=id?S.sb.from('video_stats').update(data).eq('id',id).eq('owner_id',S.user.id):S.sb.from('video_stats').insert({...data,owner_id:S.user.id});const {error}=await req;if(error)return toast(formatError(error));$('stat-form').reset();$('stat-id').value='';$('stats-form-title').textContent='Добавить опубликованный ролик';toast(views<5000?'Сохранено. Пока меньше 5000 — в прогресс не засчитывается.':'Видео сохранено');loadStats()}
function editStat(id){const v=S.stats.find(x=>x.id===id);if(!v)return;go('stats');$('stat-id').value=v.id;$('stat-name').value=v.title;$('stat-date').value=v.posted_on;$('stat-views').value=v.views;$('stat-url').value=v.source_url||'';$('stats-form-title').textContent='Редактирование видео';$('stat-form').scrollIntoView({behavior:'smooth',block:'center'})}
async function deleteStat(id){if(!checkAuth()||!confirm('Удалить запись видео?'))return;const {error}=await S.sb.from('video_stats').delete().eq('id',id).eq('owner_id',S.user.id);if(error)return toast(formatError(error));loadStats()}
function shiftMonth(n){const [y,m]=S.month.split('-').map(Number),d=new Date(y,m-1+n,1);S.month=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');renderStats()}
function legacyNotice(){if(!signed())return;try{const raw=JSON.parse(localStorage.getItem('YaneCLIBB_v9_records')||'null');const exists=Array.isArray(raw?.entries)&&raw.entries.length>0;const flag=localStorage.getItem('ycl11-imported-'+S.user.id);$('stat-import').hidden=!(exists&&!flag)}catch{$('stat-import').hidden=true}}
async function importLegacy(){if(!checkAuth())return;if(!confirm('Импортировать старые записи текущего браузера в этот аккаунт? Убедись, что это твои данные.'))return;try{const raw=JSON.parse(localStorage.getItem('YaneCLIBB_v9_records')||'null');let imported=0;for(const item of (raw?.entries||[])){const date=item.date,views=Number(item.views);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isSafeInteger(views)||views<0)continue;const legacyId=String(item.id||date+'-'+imported).slice(0,150);const {error}=await S.sb.from('video_stats').upsert({owner_id:S.user.id,posted_on:date,title:String(item.title||'Видео из v10').slice(0,120),views,legacy_id:legacyId},{onConflict:'owner_id,legacy_id'});if(error)throw error;imported++}localStorage.setItem('ycl11-imported-'+S.user.id,'1');toast('Перенесено записей: '+imported);await loadStats()}catch(e){toast('Импорт: '+formatError(e))}}
// Editable lessons from Supabase, with language-specific content when available.
async function loadLessons(){if(!S.sb){renderLessons();return}const {data,error}=await S.sb.from('lessons').select('*').order('sort_order',{ascending:true}).limit(250);if(error){html('lessons-list','<div class="empty">Уроки недоступны: '+esc(error.message)+'</div>');return}S.lessons=data||[];renderLessons()}
function localized(obj){return String(obj?.[S.lang]||obj?.ru||obj?.en||obj?.uk||'')}
function renderLessons(){const text=($('school-search').value||'').toLowerCase(),category=$('school-category').value||'all',level=$('school-level').value||'all';const cats=[...new Set(S.lessons.map(x=>x.category))];const old=$('school-category').value;html('school-category','<option value="all">Все направления</option>'+cats.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join(''));$('school-category').value=cats.includes(old)?old:'all';const filtered=S.lessons.filter(x=>(category==='all'||x.category===category)&&(level==='all'||x.difficulty===level)&&(!text||(localized(x.title_i18n)+' '+localized(x.summary_i18n)+' '+x.category).toLowerCase().includes(text)));html('lessons-list',filtered.length?filtered.map(l=>`<article class="card lesson-card"><span class="tag">${esc(l.category)}</span><span class="tag">${esc(l.difficulty)}</span><h3>${esc(localized(l.title_i18n))}</h3><p>${esc(localized(l.summary_i18n))}</p><button class="btn btn-secondary" data-lesson="${esc(l.id)}">Читать урок →</button></article>`).join(''):'<div class="empty">Уроков пока нет или ничего не найдено. Добавить материалы может администратор.</div>')}
function openLesson(id){const l=S.lessons.find(x=>x.id===id);if(!l)return;go('school');const el=$('lessons-list');html('lessons-list',`<div class="card" style="grid-column:1/-1"><button class="btn btn-secondary" id="lesson-back">← Все уроки</button><h2 style="margin-top:18px">${esc(localized(l.title_i18n))}</h2><span class="role-label">${esc(l.category)} · ${esc(l.difficulty)}</span><div class="lesson-detail">${esc(localized(l.content_i18n))}</div>${safeUrl(l.video_url)?`<a href="${esc(safeUrl(l.video_url))}" target="_blank" rel="noopener noreferrer" class="btn btn-secondary">Открыть видеоурок ↗</a>`:''}<button class="btn btn-primary" data-ask-lesson="${esc(l.id)}">✦ Спросить ЯнеИИ</button></div>`)}
const faq=[
 ['Как начать делать нарезки?','1. Выбери стрим с понятной сценой и эмоцией.\n2. Найди момент, который можно понять без длинного контекста.\n3. В CapCut создай проект 9:16, импортируй фрагмент, обрежь паузы.\n4. Добавь читаемые субтитры и проверь звук.\n5. Экспортируй 1080×1920, проверь ролик на телефоне.'],
 ['Почему видео мало набирает просмотров?','Сначала проверь удержание первых секунд, а не только лайки. Убери вступление до главного события. Сравни 3 варианта первого кадра. Проверь, читаются ли субтитры и понятна ли сцена незнакомому зрителю. Просмотры зависят и от аудитории, времени и алгоритмов; точной гарантии нет.'],
 ['Как выбрать лучший момент стрима?','Ищи неожиданную эмоцию, действие с понятной ставкой, короткий конфликт или завершённую шутку. Отметь начало и кульминацию. Оставь 1–2 секунды контекста, затем быстро переходи к событию.'],
 ['Как сделать эффект зависания в CapCut?','Открой проект и поставь курсор на моменте. Выдели клип, найди Freeze/«Заморозка» (название и расположение зависят от версии). Укороти созданный стоп-кадр. Добавь звук или приближение, чтобы эффект подчёркивал реакцию.'],
 ['Почему видео теряет качество?','Проверь качество исходника: экспорт не восстановит детали, которых нет. Отключи повторные перекодирования и чрезмерный зум. Выбери разрешение 1080×1920 и частоту кадров под исходник. Для текста используй достаточный размер и контраст.'],
 ['Как сделать плавный переход?','Совмести движение объектов в соседних сценах, затем используй короткий переход. Не смешивай много разных эффектов в одном ролике. Для динамичных нарезок часто лучше работает обычная склейка на действии.'],
 ['Какие настройки экспорта для TikTok?','Обычно подходит вертикальный формат 9:16 и 1080×1920. Сохраняй исходную частоту кадров (30 или 60 fps при соответствующем исходнике), кодек H.264/MP4 и достаточно высокий битрейт. Перед публикацией проверь итоговый файл и звук.'],
 ['Как улучшить звук?','Сначала настрой разборчивость голоса, затем уменьшай музыку до уровня фона. Используй плавные автоматизации громкости на музыкальных акцентах. Проверь клиппинг и резкие перепады в наушниках и динамике телефона.'],
 ['Как сделать субтитры?','Сгенерируй автоматические субтитры в CapCut и обязательно проверь распознавание. Разбей строки на короткие фразы, расположи текст вне системных кнопок TikTok и используй контраст с фоном.'],
 ['Как выбрать музыку?','Выбирай разрешённую для публикации дорожку, темп которой подходит сцене. Начни с лёгкого фона, затем усиливай акценты. Учитывай авторские права и региональные ограничения платформы.'],
 ['Как исправить рассинхронизацию звука?','Проверь, не отличается ли FPS исходника и проекта. Найди первый заметный удар звука, совмести его с действием на таймлайне. Если смещение нарастает, перекодируй переменную частоту кадров в постоянную перед монтажом.'],
 ['Как правильно использовать эффекты?','Каждый эффект должен помогать смыслу. Используй простое увеличение для акцента, мягкое размытие движения при необходимости и минимум декоративных переходов. Сравни результат с версией без эффекта.'],
 ['Как сделать динамичный монтаж?','Сначала собери сюжет. Удали пустые паузы, подрежь начало до первого действия, чередуй планы только там, где это помогает. Не режь каждую секунду просто ради скорости.'],
 ['Почему видео размытое?','Проверь разрешение исходного фрагмента, масштабирование и повторную компрессию. Если исходник 720p, экспорт 1080p не создаст новых деталей. Избегай многократной передачи видео через мессенджеры.'],
 ['Как улучшить цветокоррекцию?','Сначала исправь экспозицию и баланс белого, затем осторожно меняй контраст и насыщенность. Проверяй тон кожи и пересветы. На телефоне цвета часто отличаются от монитора.'],
 ['Как определить слабые места в монтаже?','Посмотри ролик без звука и отдельно только со звуком. Отметь отрезки, где непонятно действие, есть тишина или слишком мелкий текст. Попроси человека без контекста объяснить сюжет после просмотра.']
];
function renderDiagnostics(){const q=$('diagnosis-search').value.trim().toLowerCase();const arr=faq.filter(([a,b])=>(a+' '+b).toLowerCase().includes(q));html('diagnostics-list',arr.length?arr.map(([a,b],i)=>`<details class="diag-item"><summary>${esc(a)}</summary><div class="diag-content">${esc(b)}</div><button class="btn btn-secondary" data-ask-faq="${esc(a)}">✦ Спросить ЯнеИИ</button></details>`).join(''):'<div class="empty">Нет подходящих ответов. Можно задать вопрос ЯнеИИ.</div>')}
// Gemini API: requests are authenticated and server-side account cooldown is atomic.
async function loadAIHistory(){if(!signed())return;const {data,error}=await S.sb.from('ai_messages').select('id,question,answer,created_at').eq('owner_id',S.user.id).order('created_at',{ascending:false}).limit(25);if(error)return;S.aiHistory=(data||[]).reverse().flatMap(x=>[{role:'user',content:x.question},{role:'assistant',content:x.answer}]);renderAIHistory()}
function renderAIHistory(){html('ai-messages',S.aiHistory.length?S.aiHistory.map(m=>`<div class="${m.role==='user'?'ai-question':'ai-answer'}">${m.role==='assistant'?'<b>ЯнеИИ ✦</b>':''}<p>${esc(m.content)}</p></div>`).join(''):'<div class="ai-answer"><b>ЯнеИИ ✦</b><p>Привет! Я помогу разобраться с монтажом, переходами, музыкой и продвижением нарезок.</p></div>');$('ai-messages').scrollTop=$('ai-messages').scrollHeight}
function cooldownLeft(){const at=S.profile?.ai_last_used;if(!at)return 0;return Math.max(0,Math.ceil((new Date(at).getTime()+60000-Date.now())/1000))}
function updateAICooldown(){const n=cooldownLeft();$('ai-cooldown').textContent= !signed()?'Для ЯнеИИ необходим аккаунт.':n?`Следующий вопрос через ${n} секунд`:'Можно задать следующий вопрос. Не чаще одного запроса в 60 секунд.';$('ai-send').disabled=S.aiBusy||n>0||!signed()}
async function fileAsJpeg(file){return await new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{try{const c=document.createElement('canvas');const scale=Math.min(1,950/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const output=c.toDataURL('image/jpeg',.77);URL.revokeObjectURL(url);resolve(output)}catch(e){URL.revokeObjectURL(url);reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Изображение не открылось'))};img.src=url})}
async function aiFileChanged(){const f=$('ai-file').files?.[0];if(!f)return;if(f.type.startsWith('video/')){
 S.aiImage=null;
 if(!['video/mp4','video/webm','video/quicktime'].includes(f.type)||f.size>150*1024*1024){S.aiVideoFile=null;return toast('Видео: MP4, WebM или MOV до 150 МБ')}
 if(!cfg.videoWorkerUrl){S.aiVideoFile=null;$('ai-file').value='';$('ai-attachment').hidden=false;$('ai-attachment').textContent='Анализ видео и звука готов в исходниках, но видеосервер ещё не подключён. Администратору нужно развернуть video-worker и указать videoWorkerUrl в config.js.';return}
 S.aiVideoFile=f;$('ai-attachment').hidden=false;$('ai-attachment').textContent='🎬 '+f.name+' ('+(f.size/1048576).toFixed(1)+' МБ). Будет загружено на видеосервер и Google Gemini вместе со звуком.';return}
 S.aiVideoFile=null;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8e6)return toast('Выбери JPEG/PNG/WebP до 8 МБ');try{S.aiImage=await fileAsJpeg(f);S.aiImageName=f.name;$('ai-attachment').hidden=false;$('ai-attachment').textContent='📎 '+f.name+' — кадр прикреплён. Будет отправлен Gemini при вопросе.'}catch(e){toast(formatError(e))}}
function aiContext(question){const r=S.latestReport;if(!r)return undefined;const match=question.match(/(?:^|\D)(\d{1,3})\s*(?:-?\s*(?:я|й|ой|st|nd|rd|th))?\s*(?:секунд|сек\.?|с\b|second|sec)/i)||question.match(/(\d{1,2}):(\d{2})/);const time=match?(match[2]!==undefined?Number(match[1])*60+Number(match[2]):Number(match[1])):null;let segments=r.semantic?.segments||[];if(time!==null)segments=segments.filter(s=>s.start<=time&&s.end>=time);else segments=segments.slice(0,4);const clean=segments.map(s=>({start:s.start,end:s.end,analysis:s.analysis}));return {metadata:r.metadata,audio:r.audio,sceneCuts:(r.sceneCuts||[]).slice(0,150),segments:clean}}
async function sendAI(){if(!checkAuth()||S.aiBusy)return;if(S.aiVideoFile)return sendVideoAnalysis();const text=$('ai-question').value.trim();if(!text&&!S.aiImage)return toast('Напиши вопрос или прикрепи фото');if(cooldownLeft()>0)return toast('Подожди '+cooldownLeft()+' секунд');const {data:{session}}=await S.sb.auth.getSession();if(!session?.access_token)return toast('Сессия закончилась — войди снова');S.aiBusy=true;updateAICooldown();$('ai-question').value='';S.aiHistory.push({role:'user',content:text||'Проанализируй прикреплённое изображение'});renderAIHistory();const placeholder=document.createElement('div');placeholder.className='ai-answer';placeholder.textContent='ЯнеИИ думает…';$('ai-messages').appendChild(placeholder);$('ai-messages').scrollTop=$('ai-messages').scrollHeight;try{const frames=S.aiImage?[{time:0,image:S.aiImage}]:[];const res=await fetch(cfg.aiFunction||'/api/yaneai',{method:'POST',headers:{'content-type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({message:text,history:S.aiHistory.slice(0,-1).slice(-12),frames,language:S.lang,report:aiContext(text)})});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error(data.error||'Ошибка ЯнеИИ ('+res.status+')');S.aiHistory.push({role:'assistant',content:data.answer});S.profile.ai_last_used=new Date().toISOString();S.aiImage=null;$('ai-file').value='';$('ai-attachment').hidden=true;const {error}=await S.sb.from('ai_messages').insert({owner_id:S.user.id,question:(text||'Разбор изображения').slice(0,4500),answer:data.answer.slice(0,16000)});if(error)console.warn('AI history save:',error.message);renderAIHistory()}catch(e){S.aiHistory.pop();$('ai-question').value=text;toast(formatError(e));renderAIHistory()}finally{placeholder.remove();S.aiBusy=false;updateAICooldown()}}
async function clearAI(){if(!checkAuth())return;if(!confirm('Удалить историю ЯнеИИ для этого аккаунта?'))return;const {error}=await S.sb.from('ai_messages').delete().eq('owner_id',S.user.id);if(error)return toast(formatError(error));S.aiHistory=[];renderAIHistory();toast('История удалена')}
function askAI(question){if(!checkAuth())return;go('ai');$('ai-question').value=question;$('ai-question').focus()}

async function loadLatestReport(){if(!signed())return;const {data,error}=await S.sb.from('ai_reports').select('report').eq('owner_id',S.user.id).order('created_at',{ascending:false}).limit(1);if(!error)S.latestReport=data?.[0]?.report||null}
function timestamp(seconds){const n=Math.max(0,Number(seconds)||0);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(Math.floor(n%60)).padStart(2,'0')}
function videoReportText(report){const lines=[];const meta=report.metadata||{};lines.push('🎬 Полный анализ видео со звуком (Gemini + FFmpeg)');lines.push('Длительность: '+timestamp(meta.duration)+' · '+(meta.width||'?')+'×'+(meta.height||'?')+' · '+(meta.fps??'?')+' FPS');lines.push('Аудиодорожка: '+(meta.hasAudio?'Есть':'Нет')+' · Громкость LUFS: '+(report.audio?.integratedLufs??'нет измерения'));
 lines.push('Вероятные склейки по FFmpeg: '+(report.sceneCuts||[]).slice(0,90).map(timestamp).join(', '));
 for(const s of report.semantic?.segments||[]){const a=s.analysis||{};lines.push('\n━━━ '+timestamp(s.start)+'–'+timestamp(s.end)+' ━━━');
 if(a.summary)lines.push('Содержание: '+a.summary);if(a.speech)lines.push('Речь: '+a.speech);if(a.music)lines.push('Музыка: '+a.music);
 for(const x of a.findings||[])lines.push((x.time||'Без таймкода')+' · '+(x.category||'Наблюдение')+': '+(x.observation||'')+' → '+(x.recommendation||''));
 for(const [k,v] of Object.entries(a.scores||{})){if(v&&typeof v==='object'&&v.score!=null)lines.push(k+': '+v.score+'/10. '+(v.reason||''))}}
 const cats=['editing','pacing','sound','effects','picture'];const labels={editing:'Монтаж',pacing:'Динамика',sound:'Звук',effects:'Эффекты',picture:'Качество картинки'};const totals=[];
 for(const c of cats){const points=(report.semantic?.segments||[]).map(s=>s.analysis?.scores?.[c]).filter(v=>v&&Number.isFinite(Number(v.score))&&Number(v.score)>=0&&Number(v.score)<=10);if(points.length){const avg=points.reduce((sum,v)=>sum+Number(v.score),0)/points.length;totals.push(avg);lines.push(labels[c]+': '+avg.toFixed(1)+'/10 — средняя оценка по '+points.length+' сегментам; причины выше.')}else lines.push(labels[c]+': недостаточно данных для оценки.')}
 if(totals.length)lines.push('Общая оценка: '+(totals.reduce((s,v)=>s+v,0)/totals.length).toFixed(1)+'/10 — средняя по доступным оценкам, не прогноз охватов.');
 lines.push('\nВажно: исходный видеофайл и звуковая дорожка переданы модели, FFmpeg измеряет динамику всего таймлайна; Gemini может сэмплировать кадры и иногда ошибаться. Не гарантирует просмотры.');
 return lines.join('\n')}
async function sendVideoAnalysis(){if(!checkAuth()||S.aiBusy||!S.aiVideoFile)return;const file=S.aiVideoFile,base=String(cfg.videoWorkerUrl||'').replace(/\/$/,'');if(!safeUrl(base))return toast('Сервер анализа ещё не настроен');
 if(cooldownLeft()>0)return toast('Следующий запрос через '+cooldownLeft()+' секунд');
 if(!confirm('Видео «'+file.name+'» со звуком будет загружено на отдельный видеосервер и передано Google Gemini для анализа. Продолжить?'))return;
 const {data:{session}}=await S.sb.auth.getSession();if(!session?.access_token)return toast('Выполни вход снова');
 S.aiBusy=true;updateAICooldown();const question=$('ai-question').value.trim();const placeholder=document.createElement('div');placeholder.className='ai-answer';placeholder.textContent='Загрузка и анализ всего видео вместе со звуком…';$('ai-messages').appendChild(placeholder);$('ai-messages').scrollTop=$('ai-messages').scrollHeight;
 try{const form=new FormData();form.append('file',file,file.name);form.append('question',question);form.append('language',S.lang);const result=await fetch(base+'/analyze',{method:'POST',headers:{Authorization:'Bearer '+session.access_token},body:form});const data=await result.json().catch(()=>({}));if(!result.ok)throw Error(data.detail||'Видеоанализ: HTTP '+result.status);if(!data.semantic?.fullFileUploaded)throw Error('Анализ полного видео не подтверждён');
 const report={metadata:data.metadata,audio:data.audio,sceneCuts:data.sceneCuts,semantic:data.semantic};S.latestReport=report;const summary=videoReportText(data);S.aiHistory.push({role:'user',content:'Разбери видео '+file.name+(question?' — '+question:'')},{role:'assistant',content:summary});$('ai-question').value='';S.aiVideoFile=null;$('ai-file').value='';$('ai-attachment').hidden=true;renderAIHistory();
 const store=await S.sb.from('ai_reports').insert({owner_id:S.user.id,title:file.name.slice(0,160),report});if(store.error)toast('Видео разобрано, но отчёт не сохранился: '+formatError(store.error));
 const message=await S.sb.from('ai_messages').insert({owner_id:S.user.id,question:('Разбор видео '+file.name).slice(0,4500),answer:summary.slice(0,16000)});if(message.error)console.warn('Report history save',message.error.message);
 const {data:profile}=await S.sb.from('profiles').select('ai_last_used').eq('id',S.user.id).maybeSingle();if(profile)S.profile.ai_last_used=profile.ai_last_used;
 }catch(e){toast('Видеоанализ: '+formatError(e))}finally{placeholder.remove();S.aiBusy=false;updateAICooldown()}}
// Release history starts with unpublished draft v1; only actual published versions are shown.
async function loadReleases(){if(!S.sb)return;const {data,error}=await S.sb.from('releases').select('*').order('version',{ascending:false});if(error)return;S.releases=data||[];renderReleases()}
function renderReleases(){const visible=S.releases.filter(r=>r.is_published);html('updates-list',visible.length?visible.map(r=>`<div class="card"><span class="role-label">v${esc(r.version)}</span><h3>${esc(r.title)}</h3><small class="muted">${esc(fmtDate(r.published_at||r.created_at))}</small><p>${esc(r.description)}</p><div class="lesson-detail">${esc(r.changes)}</div></div>`).join(''):'<div class="empty">Опубликованных выпусков пока нет. Администратор опубликует v1 после проверки установки.</div>')}
// Admin panel: all views read real database data, all writes have server RLS/RPC checks.
async function renderAdmin(){if(!requireAdmin())return;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===S.adminTab));html('admin-content','<div class="card"><p>Загрузка данных…</p></div>');try{if(S.adminTab==='reports')await adminReports();else if(S.adminTab==='users')await adminUsers();else if(S.adminTab==='submissions')await adminSubmissions();else if(S.adminTab==='releases')await adminReleases();else if(S.adminTab==='lessons')await adminLessons();else if(S.adminTab==='settings')await adminSettings();else if(S.adminTab==='logs')await adminLogs()}catch(e){html('admin-content','<div class="empty">Ошибка: '+esc(formatError(e))+'</div>')}}
async function adminReports(){const {data,error}=await S.sb.from('chat_reports').select('id,message_id,reporter_id,reason,status,created_at').eq('resolved',false).order('created_at',{ascending:false}).limit(100);if(error)throw error;const reports=data||[];const ids=reports.map(x=>x.message_id),{data:msgs}=ids.length?await S.sb.from('chat_messages').select('id,author_id,body,created_at,removed').in('id',ids):{data:[]};const byMsg=new Map((msgs||[]).map(x=>[x.id,x]));await loadProfiles();const byUser=new Map(S.profiles.map(x=>[x.id,x]));html('admin-content',`<div class="card"><h3>🚩 Открытые жалобы: ${reports.length}</h3>${reports.length?reports.map(r=>{const msg=byMsg.get(r.message_id),p=byUser.get(msg?.author_id),reporter=byUser.get(r.reporter_id);return `<article class="card"><b>${esc(r.reason)}</b><p>От: ${esc(reporter?.username||r.reporter_id)} · ${esc(fmtDate(r.created_at))}</p><div class="notice"><b>Сообщение ${msg?.removed?'(уже скрыто)':''}: ${esc(p?.username||'Участник')}</b><p>${esc(msg?.body||'Сообщение недоступно')}</p></div><div class="table-actions"><button data-handle-report="${esc(r.id)}" data-decision="remove">Удалить сообщение</button><button data-handle-report="${esc(r.id)}" data-decision="resolved">Рассмотрено</button><button data-handle-report="${esc(r.id)}" data-decision="dismissed">Отклонить жалобу</button>${msg?`<button data-admin-user="${esc(msg.author_id)}">Управлять автором</button>`:''}</div></article>`}).join(''):'<div class="empty">Новых жалоб нет.</div>'}</div>`)}
async function resolveReport(id,decision){if(!requireAdmin())return;const reason=prompt('Комментарий администратора (необязательно):','');if(reason===null)return;const {error}=await S.sb.rpc('v11_handle_report',{report_id:id,decision,note:reason});if(error)return toast(formatError(error));toast('Жалоба обработана');renderAdmin()}
async function adminUsers(){await loadProfiles();const users=S.profiles;html('admin-content',`<div class="card"><h3>Участники (${users.length})</h3><input class="field-search" id="admin-search-users" placeholder="Найти по никнейму"><div id="admin-users-list"></div></div><div id="admin-user-actions"></div>`);renderAdminUsersList()}
function renderAdminUsersList(){const input=$('admin-search-users');if(!input)return;const q=input.value.toLowerCase(),users=S.profiles.filter(p=>p.username?.toLowerCase().includes(q));html('admin-users-list',users.length?`<div class="table-scroll"><table><thead><tr><th>Ник</th><th>Роль</th><th>Регистрация</th><th>Активность</th><th>Статус</th><th></th></tr></thead><tbody>${users.map(p=>`<tr><td>${esc(p.username)}</td><td>${roleLabel(p)}</td><td>${esc(fmtDate(p.created_at))}</td><td>${Math.round((p.activity_seconds||0)/60)} мин</td><td>${p.is_banned?'Заблокирован':'Активен'}</td><td><button class="btn btn-secondary" data-admin-user="${esc(p.id)}">Управлять</button></td></tr>`).join('')}</tbody></table></div>`:'<p>Пользователи не найдены.</p>')}
function manageUser(id){if(!requireAdmin())return;const p=S.profiles.find(x=>x.id===id);if(!p)return toast('Аккаунт не найден');S.selectedUser=id;html('admin-user-actions',`<div class="card"><h3>⚙ ${esc(p.username)} · ${esc(roleLabel(p))}</h3><p>Изменения ролей, блокировки и ограничения записываются в серверный журнал.</p><div class="table-actions"><button data-action-user="role_user">👤 Пользователь</button><button data-action-user="role_clipper">🎬 Основной нарезчик</button><button data-action-user="role_admin">🛡 Администратор</button><button data-action-user="mute" data-seconds="300">Мут 5 минут</button><button data-action-user="mute" data-seconds="600">Мут 10 минут</button><button data-action-user="mute" data-seconds="1800">Мут 30 минут</button><button data-action-user="mute" data-seconds="604800">Мут 7 дней</button><button data-action-user="unmute">Снять мут</button><button data-action-user="ban">Заблокировать</button><button data-action-user="unban">Разблокировать</button></div>${p.chat_muted_until?`<p>Чат закрыт до: ${esc(fmtDate(p.chat_muted_until))}</p>`:''}</div>`);$('admin-user-actions').scrollIntoView({behavior:'smooth',block:'center'})}
async function adminAct(action,seconds){if(!requireAdmin()||!S.selectedUser)return;const reason=prompt('Причина действия (запишется в журнал):','');if(reason===null)return;if(!confirm('Подтвердить действие «'+action+'»?'))return;const {error}=await S.sb.rpc('v11_admin_action',{action_name:action,target_user:S.selectedUser,reason_text:reason,mute_seconds:seconds||0});if(error)return toast(formatError(error));toast('Действие выполнено');renderAdmin()}
async function adminSubmissions(){const {data,error}=await S.sb.from('video_submissions').select('*').order('created_at',{ascending:false}).limit(100);if(error)throw error;html('admin-content',`<div class="card"><h3>▣ Заявки на публикацию</h3>${data?.length?data.map(v=>`<article class="card"><b>${esc(v.title)}</b><span class="role-label">${esc(v.status)}</span><p>Автор: ${esc(v.author_credit)} · ${esc(fmtDate(v.created_at))}</p><p>${esc(v.description)}</p><a class="btn btn-secondary" href="${esc(safeUrl(v.source_url)||'#')}" target="_blank" rel="noopener noreferrer">Посмотреть оригинал ↗</a>${v.status==='pending'?`<div class="table-actions"><button data-review-video="${esc(v.id)}" data-decision="approved">✅ Одобрить</button><button data-review-video="${esc(v.id)}" data-decision="rejected">❌ Отклонить</button></div>`:`<p>Комментарий: ${esc(v.review_reason||'—')}</p>`}</article>`).join(''):'<div class="empty">Заявок пока нет.</div>'}</div>`)}
async function reviewVideo(id,decision){const reason=prompt(decision==='rejected'?'Причина отклонения:':'Комментарий (необязательно):','');if(reason===null)return;const {error}=await S.sb.rpc('v11_review_video',{item_id:id,decision,reason_text:reason});if(error)return toast(formatError(error));toast('Решение сохранено');renderAdmin();loadVideos()}
async function adminReleases(){await loadReleases();const max=Math.max(0,...S.releases.map(v=>v.version));html('admin-content',`<div class="admin-grid"><div class="card"><h3>✎ Новый релиз или черновик</h3><form id="release-form" class="stack-form"><label>Номер версии<input type="number" name="version" value="${max+1}" min="1" required></label><label>Название<input name="title" minlength="3" maxlength="140" required></label><label>Описание<textarea name="description" rows="2"></textarea></label><label>Подробности<textarea name="changes" rows="5"></textarea></label><label><input type="checkbox" name="is_published"> Публиковать сразу (только проверенные изменения)</label><button class="btn btn-primary" type="submit">Сохранить выпуск</button></form></div><div class="card"><h3>Версии</h3>${S.releases.map(r=>`<div class="notice"><b>v${esc(r.version)} — ${esc(r.title)}</b><p>${r.is_published?'Опубликовано':'Черновик'} · ${esc(fmtDate(r.created_at))}</p><div class="table-actions"><button data-edit-release="${esc(r.id)}">Редактировать</button>${!r.is_published?`<button data-publish-release="${esc(r.id)}">Опубликовать</button>`:''}<button data-remove-release="${esc(r.id)}">Удалить</button></div></div>`).join('')}</div></div>`)}
async function saveRelease(e){e.preventDefault();const form=e.target,f=new FormData(form),id=form.dataset.id;const record={version:Number(f.get('version')),title:String(f.get('title')).trim(),description:String(f.get('description')||''),changes:String(f.get('changes')||''),is_published:!!f.get('is_published')};if(record.is_published)record.published_at=new Date().toISOString();const req=id?S.sb.from('releases').update(record).eq('id',id):S.sb.from('releases').insert(record);const {error}=await req;if(error)return toast(formatError(error));toast('Релиз сохранён');renderAdmin()}
function editRelease(id){const r=S.releases.find(x=>String(x.id)===String(id)),form=$('release-form');if(!r||!form)return;form.dataset.id=r.id;for(const k of ['version','title','description','changes'])form.elements[k].value=r[k];form.elements.is_published.checked=r.is_published;form.scrollIntoView({behavior:'smooth'})}
async function releaseAction(id,action){if(!requireAdmin())return;const r=S.releases.find(x=>String(x.id)===String(id));if(!r)return;if(!confirm(action==='publish'?'Опубликовать проверенную версию v'+r.version+'?':'Удалить запись?'))return;const q=action==='publish'?S.sb.from('releases').update({is_published:true,published_at:new Date().toISOString()}).eq('id',id):S.sb.from('releases').delete().eq('id',id);const {error}=await q;if(error)return toast(formatError(error));toast('Сохранено');renderAdmin()}
async function adminLessons(){await loadLessons();html('admin-content',`<div class="admin-grid"><div class="card"><h3>✂ Создать/изменить урок</h3><form id="lesson-form" class="stack-form"><label>Категория<input name="category" required placeholder="CapCut ПК"></label><label>Уровень<select name="difficulty"><option value="beginner">Начинающий</option><option value="intermediate">Средний</option><option value="advanced">Продвинутый</option></select></label><label>Заголовок RU<input name="title" required></label><label>Краткое описание RU<textarea name="summary" rows="2"></textarea></label><label>Текст урока RU<textarea name="content" rows="9" required></textarea></label><label>Ссылка на видеоурок (необязательно)<input type="url" name="video_url"></label><label>Порядок<input type="number" name="sort_order" value="0"></label><label><input type="checkbox" name="is_published" checked> Опубликовать</label><button class="btn btn-primary" type="submit">Сохранить урок</button></form></div><div class="card"><h3>Материалы: ${S.lessons.length}</h3>${S.lessons.map(l=>`<div class="notice"><b>${esc(localized(l.title_i18n))}</b><p>${esc(l.category)} · ${esc(l.difficulty)} · ${l.is_published?'Опубликован':'Черновик'}</p><div class="table-actions"><button data-edit-lesson="${esc(l.id)}">Редактировать</button><button data-delete-lesson="${esc(l.id)}">Удалить</button></div></div>`).join('')}</div></div>`)}
async function saveLesson(e){e.preventDefault();const form=e.target,f=new FormData(form),id=form.dataset.id,old=S.lessons.find(x=>x.id===id);const row={category:String(f.get('category')).trim(),difficulty:f.get('difficulty'),title_i18n:{...(old?.title_i18n||{}),ru:String(f.get('title'))},summary_i18n:{...(old?.summary_i18n||{}),ru:String(f.get('summary')||'')},content_i18n:{...(old?.content_i18n||{}),ru:String(f.get('content'))},video_url:safeUrl(f.get('video_url'))||null,sort_order:Number(f.get('sort_order')||0),is_published:!!f.get('is_published')};const q=id?S.sb.from('lessons').update(row).eq('id',id):S.sb.from('lessons').insert(row);const {error}=await q;if(error)return toast(formatError(error));toast('Урок сохранён');renderAdmin()}
function editLesson(id){const l=S.lessons.find(x=>x.id===id),f=$('lesson-form');if(!l||!f)return;f.dataset.id=l.id;for(const k of ['category','difficulty','video_url','sort_order'])f.elements[k].value=l[k]??'';for(const k of ['title','summary','content'])f.elements[k].value=l[k+'_i18n']?.ru||'';f.elements.is_published.checked=l.is_published;f.scrollIntoView({behavior:'smooth'})}
async function deleteLesson(id){if(!confirm('Удалить урок без восстановления?'))return;const {error}=await S.sb.from('lessons').delete().eq('id',id);if(error)return toast(formatError(error));renderAdmin()}
async function adminSettings(){const s=S.settings||{};html('admin-content',`<div class="card" style="max-width:800px"><h3>⚙ Настройки сообщества</h3><form id="settings-form" class="stack-form"><label>Количество мест в основе<input type="number" name="capacity" min="1" max="1000" value="${Number(s.capacity)||10}" required></label><label>Подтверждённые официальные правила<textarea name="official_rules" rows="7">${esc(s.official_rules||'')}</textarea></label><label>Дополнительные правила сообщества<textarea name="extra_rules" rows="7">${esc(s.extra_rules||'')}</textarea></label><label>HTTPS-ссылка на вставку<input name="insert_download_url" type="url" value="${esc(s.insert_download_url||'')}"></label><button class="btn btn-primary" type="submit">Сохранить настройки</button></form><hr><h3>Загрузка утверждённого баннера правил</h3><input id="banner-input" type="file" accept="image/png,image/jpeg"><button class="btn btn-secondary" id="banner-upload">Загрузить баннер</button></div>`)}
async function saveSettings(e){e.preventDefault();const f=new FormData(e.target),capacity=Number(f.get('capacity')),url=String(f.get('insert_download_url')||'').trim();if(!Number.isInteger(capacity)||capacity<1||capacity>1000)return toast('Места: от 1 до 1000');if(url&&!safeUrl(url))return toast('Нужна HTTPS-ссылка');const {error}=await S.sb.from('site_settings').update({capacity,official_rules:String(f.get('official_rules')).slice(0,25000),extra_rules:String(f.get('extra_rules')).slice(0,25000),insert_download_url:url||null}).eq('id','main');if(error)return toast(formatError(error));toast('Настройки сохранены');await loadPublic()}
async function uploadBanner(){const file=$('banner-input')?.files?.[0];if(!file||!['image/png','image/jpeg'].includes(file.type)||file.size>5e6)return toast('Только PNG/JPEG до 5 МБ');const path='banner-'+Date.now()+(file.type==='image/png'?'.png':'.jpg');const up=await S.sb.storage.from('banners').upload(path,file,{contentType:file.type});if(up.error)return toast(formatError(up.error));const set=await S.sb.from('site_settings').update({banner_path:path}).eq('id','main');if(set.error)return toast(formatError(set.error));toast('Баннер обновлён');loadPublic()}
async function adminLogs(){const {data,error}=await S.sb.from('admin_logs').select('action,actor_id,target_id,details,created_at').order('created_at',{ascending:false}).limit(200);if(error)throw error;await loadProfiles();const byUser=new Map(S.profiles.map(p=>[p.id,p.username]));html('admin-content',`<div class="card"><h3>📋 Журнал действий</h3><input id="logs-filter" class="field-search" placeholder="Фильтр по типу события"><div id="logs-table"></div></div>`);const render=()=>{const q=$('logs-filter').value.toLowerCase();html('logs-table',`<div class="table-scroll"><table><thead><tr><th>Время</th><th>Событие</th><th>Администратор</th><th>Детали</th></tr></thead><tbody>${(data||[]).filter(l=>(l.action+' '+(byUser.get(l.actor_id)||'')).toLowerCase().includes(q)).map(l=>`<tr><td>${esc(fmtDate(l.created_at))}</td><td>${esc(l.action)}</td><td>${esc(byUser.get(l.actor_id)||'Система')}</td><td>${esc(JSON.stringify(l.details||{})).slice(0,200)}</td></tr>`).join('')}</tbody></table></div>`)};$('logs-filter').addEventListener('input',render);render()}
// Event delegation: every visible control has a real handler.
document.addEventListener('click',async e=>{
const b=e.target.closest('button,a');if(!b)return;
if(b.dataset.nav){go(b.dataset.nav);return}
if(b.dataset.go){go(b.dataset.go);return}
if(b.dataset.user){openProfile(b.dataset.user);return}
if(b.dataset.reportMessage){openReport(b.dataset.reportMessage);return}
if(b.dataset.reply){const m=S.chats.find(x=>x.id===b.dataset.reply);S.reply=b.dataset.reply;$('chat-reply').hidden=false;$('chat-reply').innerHTML=`Ответ на: ${esc(m?.body?.slice(0,130)||'сообщение')} <button id="cancel-reply">✕</button>`;$('chat-input').focus();return}
if(b.dataset.deleteMessage){deleteChat(b.dataset.deleteMessage);return}
if(b.dataset.editStat){editStat(b.dataset.editStat);return}
if(b.dataset.deleteStat){deleteStat(b.dataset.deleteStat);return}
if(b.dataset.statDay){$('stat-date').value=S.month+'-'+String(b.dataset.statDay).padStart(2,'0');$('stat-name').focus();return}
if(b.dataset.aiVideo){const v=S.videos.find(x=>x.id===b.dataset.aiVideo);if(v)askAI(`Обсудим эту нарезку: «${v.title}», автор ${v.author}. Ссылка: ${v.source_url}. По одной ссылке не утверждай, что просмотрел видео. Дай критерии проверки монтажа и план анализа.`);return}
if(b.dataset.lesson){openLesson(b.dataset.lesson);return}
if(b.dataset.askLesson){const l=S.lessons.find(x=>x.id===b.dataset.askLesson);if(l)askAI('Объясни ещё подробнее: '+localized(l.title_i18n));return}
if(b.dataset.askFaq){askAI('Помоги с проблемой: '+b.dataset.askFaq+'. Дай пошаговую инструкцию для CapCut.');return}
if(b.dataset.authmode){authMode(b.dataset.authmode);return}
if(b.dataset.tab){S.adminTab=b.dataset.tab;renderAdmin();return}
if(b.dataset.handleReport){resolveReport(b.dataset.handleReport,b.dataset.decision);return}
if(b.dataset.adminUser){S.adminTab='users';if(!$('admin-users-list'))await renderAdmin();manageUser(b.dataset.adminUser);return}
if(b.dataset.actionUser){adminAct(b.dataset.actionUser,Number(b.dataset.seconds)||0);return}
if(b.dataset.reviewVideo){reviewVideo(b.dataset.reviewVideo,b.dataset.decision);return}
if(b.dataset.editRelease){editRelease(b.dataset.editRelease);return}
if(b.dataset.publishRelease){releaseAction(b.dataset.publishRelease,'publish');return}
if(b.dataset.removeRelease){releaseAction(b.dataset.removeRelease,'remove');return}
if(b.dataset.editLesson){editLesson(b.dataset.editLesson);return}
if(b.dataset.deleteLesson){deleteLesson(b.dataset.deleteLesson);return}
if(b.id==='menu-toggle'){$('app').classList.toggle('menu-open');$('scrim').hidden=!$('app').classList.contains('menu-open');return}
if(b.id==='side-close'){$('app').classList.remove('menu-open');$('scrim').hidden=true;return}
if(b.id==='theme-toggle'){setTheme(S.theme==='dark'?'light':'dark');return}
if(b.id==='account-button'||b.id==='side-account'){if(signed())openProfile();else $('auth-dialog').showModal();return}
if(b.id==='updates-button'){$('updates-dialog').showModal();loadReleases();return}
if(b.id==='create-button'||b.id==='propose-video'){if(checkAuth())$('submission-dialog').showModal();return}
if(b.id==='older-chat'){loadChat(true);return}
if(b.id==='chat-send'){sendChat();return}
if(b.id==='cancel-reply'){S.reply=null;$('chat-reply').hidden=true;return}
if(b.id==='ai-send'){sendAI();return}
if(b.id==='ai-clear'){clearAI();return}
if(b.id==='prev-month'){shiftMonth(-1);return}
if(b.id==='next-month'){shiftMonth(1);return}
if(b.id==='stat-clear'){$('stat-form').reset();$('stat-id').value='';$('stats-form-title').textContent='Добавить опубликованный ролик';return}
if(b.id==='import-legacy'){importLegacy();return}
if(b.id==='signout'){if(S.sb){await S.sb.auth.signOut();S.openedProfile=null;toast('Ты вышел из аккаунта');go('home')}return}
if(b.id==='lesson-back'){renderLessons();return}
if(b.id==='banner-upload'){uploadBanner();return}
});
document.addEventListener('submit',e=>{const id=e.target.id;const handlers={'auth-form':authSubmit,'report-form':submitReport,'submission-form':sendSubmission,'stat-form':saveStat,'profile-form':saveProfile,'release-form':saveRelease,'lesson-form':saveLesson,'settings-form':saveSettings};if(handlers[id]){e.preventDefault();Promise.resolve(handlers[id](e)).catch(err=>toast(formatError(err)))}});
$('scrim').addEventListener('click',()=>{$('app').classList.remove('menu-open');$('scrim').hidden=true});
$('language-select').addEventListener('change',e=>setLanguage(e.target.value));
$('ai-file').addEventListener('change',aiFileChanged);
$('school-search').addEventListener('input',renderLessons);
$('school-category').addEventListener('change',renderLessons);
$('school-level').addEventListener('change',renderLessons);
$('diagnosis-search').addEventListener('input',renderDiagnostics);
$('global-search').addEventListener('keydown',e=>{if(e.key!=='Enter')return;const term=e.target.value.trim();if(!term)return;go('diagnostics');$('diagnosis-search').value=term;renderDiagnostics()});
$('global-search').addEventListener('input',e=>{if(S.page==='diagnostics'){$('diagnosis-search').value=e.target.value;renderDiagnostics()}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('global-search').focus()}if(e.key==='Enter'&&e.ctrlKey&&S.page==='ai'){e.preventDefault();sendAI()}if(e.key==='Enter'&&e.ctrlKey&&S.page==='chat'){e.preventDefault();sendChat()}});
document.addEventListener('input',e=>{if(['click','mousemove','touchstart','keydown','input'].includes(e.type))S.lastAction=Date.now();if(e.target.id==='admin-search-users')renderAdminUsersList()});
for(const event of ['click','keydown','touchstart'])document.addEventListener(event,()=>{S.lastAction=Date.now()},{passive:true});
// periodic timer only updates text; enforcement lives in PostgreSQL.
setInterval(updateAICooldown,1000);
$('stat-date').value=new Date().toISOString().slice(0,10);
setTheme(S.theme);setLanguage(S.lang);$('ai-disclosure').textContent=cfg.videoWorkerUrl?'Полный видеоанализ: файл со звуком передаётся отдельно на ваш видеосервер и Google Gemini после подтверждения. Отчёты доступны только владельцу аккаунта.':'Для фото кадры передаются Google Gemini. Чтобы анализировать полные видео со звуком, разверните отдельный video-worker (инструкция в README).';authMode('login');renderDiagnostics();renderLessons();renderVideos();renderRules();renderClippers();renderStats();
const initial=location.hash.slice(1);if(['home','ai','school','diagnostics','videos','clippers','chat','stats','rules','profile'].includes(initial))go(initial);
initBackend();
})();
